module measured;
import "std/queue.nex" as q;
import "std/stack.nex" as s;
import "std/deque.nex" as d;
import "std/priority_queue.nex" as p;
fn main()->unit!{io}{
 var queue:q::Queue<i64>=q::empty();var stack:s::Stack<i64>=s::empty();
 var deque:d::Deque<i64>=d::empty();var priority:p::PriorityQueue<i64>=p::empty<i64>();
 var index:i64=0;
 while index<256{queue=q::enqueue(queue,index+1);stack=s::push_value(stack,index+1);deque=d::push_back(deque,index+1);priority=p::push_value(priority,index+1);index=index+1;}
 var total:i64=0;index=0;
 while index<256{
  let a:q::Popped<i64>=unwrap(q::dequeue(queue));let b:s::Popped<i64>=unwrap(s::pop(stack));
  let c:d::Popped<i64>=unwrap(d::pop_front(deque));let e:p::Popped<i64>=unwrap(p::pop(priority));
  assert(a.value==index+1&&b.value==256-index&&c.value==index+1&&e.value==index+1);
  total=total+a.value+b.value+c.value+e.value;
  queue=a.queue;stack=b.stack;deque=c.deque;priority=e.queue;index=index+1;
 }
 assert(q::is_empty(queue)&&s::is_empty(stack)&&d::is_empty(deque)&&p::is_empty(priority));print(total);
}

